<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import {useApp} from '../stores/app'
import {useCustomerNotifications,notificationCategory} from '../stores/customerNotifications'
import {useBackendEvents} from '../composables/useBackendEvents'
import {displayDate} from '../utils/display-date'
const emit=defineEmits<{opened:[]}>()
const app=useApp(),route=useRoute(),notifications=useCustomerNotifications(),opened=ref(false),button=ref<HTMLButtonElement>(),popup=ref<HTMLElement>(),position=ref({top:'0px',left:'0px',width:'340px',maxHeight:'400px'})
const historyPath=computed(()=>route.path.startsWith('/customer-app/')?'/customer-app/screen-12':'/my-alerts')
function locate(){const rect=button.value?.getBoundingClientRect();if(!rect)return;const width=Math.min(360,innerWidth-24),top=rect.bottom+8;position.value={top:top+'px',left:Math.max(12,Math.min(rect.right-width,innerWidth-width-12))+'px',width:width+'px',maxHeight:Math.max(120,innerHeight-top-12)+'px'}}
async function toggle(){opened.value=!opened.value;if(opened.value){emit('opened');locate();void notifications.refresh();await nextTick();popup.value?.focus({preventScroll:true})}}
function close(focus=false){opened.value=false;if(focus)button.value?.focus({preventScroll:true})}
function outside(event:PointerEvent){if(!button.value?.contains(event.target as Node)&&!popup.value?.contains(event.target as Node))close()}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&opened.value)close(true)}
function changed(){if(opened.value)locate()}
watch(()=>route.fullPath,()=>close())
watch(()=>app.account?.id,()=>{close();notifications.reset();if(app.account?.role==='customer')void notifications.refresh()},{immediate:true})
useBackendEvents(({name,data})=>{if(name==='connected')void notifications.refresh();else if(name==='notification-new')notifications.ingest(data)})
onMounted(()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);window.addEventListener('resize',changed);window.addEventListener('scroll',changed,true)})
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);window.removeEventListener('resize',changed);window.removeEventListener('scroll',changed,true)})
</script>
<template><span class="notification-bell"><button ref="button" type="button" class="header-alert-link" :aria-label="app.unread?'알림 '+app.unread+'건':'알림'" :aria-expanded="opened" aria-controls="customer-notification-popup" @click="toggle"><svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4M12 2V1"/></svg><span v-if="app.unread" class="header-alert-count" aria-hidden="true">{{app.unread>99?'99+':app.unread}}</span></button><Teleport to="body"><section v-if="opened" id="customer-notification-popup" ref="popup" class="customer-notification-popup" :style="position" tabindex="-1" aria-label="최근 알림"><header><h2>최근 알림 <small v-if="app.unread">{{app.unread}}건 안 읽음</small></h2><button type="button" aria-label="알림 창 닫기" @click="close(true)">×</button></header><div class="notification-popup-body"><p v-if="notifications.loading" role="status">알림을 불러오는 중입니다.</p><div v-else-if="notifications.error" role="alert"><p>{{notifications.error}}</p><button type="button" @click="notifications.refresh">다시 불러오기</button></div><ul v-else-if="notifications.recent.length"><li v-for="item in notifications.recent" :key="item.id" :class="{unread:!item.read}"><RouterLink :to="{path:historyPath,query:{notification:item.id}}" @click="close()"><span class="notification-popup-category">{{notificationCategory(item.category)}}</span><strong>{{item.title}}</strong><span class="notification-popup-copy">{{item.body}}</span><time>{{displayDate(item.createdAt)}}</time></RouterLink></li></ul><p v-else>새 알림이 없습니다.</p></div><footer><RouterLink :to="historyPath" @click="close()">알림 내역 전체 보기 →</RouterLink></footer></section></Teleport></span></template>
<style scoped>
.notification-bell{display:inline-flex;align-items:center;flex:0 0 40px;width:40px;height:40px}.notification-bell .header-alert-link{position:relative;display:flex;align-items:center;justify-content:center;flex:none;width:40px;min-width:40px;max-width:40px;height:40px;min-height:40px;max-height:40px;padding:0;border:0;background:transparent;color:inherit;cursor:pointer}
.notification-bell .header-alert-link>svg{display:block;position:static;flex:0 0 24px;width:24px;min-width:24px;max-width:24px;height:24px;min-height:24px;max-height:24px;transform:none}
.customer-notification-popup{position:fixed;z-index:220;display:flex;flex-direction:column;background:var(--surface,#fff);color:var(--foreground,#20252b);border:1px solid var(--line,#c9ced6);border-radius:10px;box-shadow:0 12px 36px #172a402b;overflow:hidden;font:14px/1.5 Arial,'Malgun Gothic',sans-serif}
.customer-notification-popup header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;border-bottom:1px solid var(--line,#c9ced6)}.customer-notification-popup h2{margin:0;font-size:15px}.customer-notification-popup h2 small{font-size:11px;font-weight:400;color:#64748b;margin-left:6px}.customer-notification-popup button{border:1px solid var(--line);background:var(--surface);color:inherit;min-height:32px;padding:4px 10px;border-radius:5px;cursor:pointer}.customer-notification-popup header button{font-size:22px;border:0;padding:0 6px}
.notification-popup-body{overflow:auto;min-height:0}.notification-popup-body>p,.notification-popup-body>[role=alert]{padding:16px;margin:0}.notification-popup-body ul{list-style:none;margin:0;padding:0}.notification-popup-body li+li{border-top:1px solid var(--line)}.notification-popup-body a{display:grid;gap:5px;padding:14px 16px;color:inherit;text-decoration:none}.notification-popup-body a:hover{background:#f2f6fa}.notification-popup-body .unread a{background:#edf4fb}.notification-popup-body strong{font-size:13px;overflow-wrap:anywhere}.notification-popup-category{color:#225f9b;font-size:11px}.notification-popup-copy{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;color:#64748b;font-size:12px;overflow-wrap:anywhere}.notification-popup-body time{color:#64748b;font-size:11px}.customer-notification-popup footer{padding:12px 16px;border-top:1px solid var(--line)}.customer-notification-popup footer a{color:inherit;font-size:12px;text-decoration:none}
</style>
